use cp_lib::*;

// @code begin
use cpio::*;

sol_n! {
    fn solution(
        n: usize,
        a: [usize]
    ) -> usize {
        let b = a.iter().min().unwrap();
        let c = a.iter().max().unwrap();
        (c - b) * (n - 1)
    }
}
// @code end

config:
author: Ayush Biswas

editor: "code {{ .Filename }}"

# How to generate the destination filename.
filename:
  rules:
    - site: atcoder.jp
      regex: "contests/([^/]+)/tasks/([^_]+)_([a-z]+)"
      template: "./src/bin/{{ index .Captures 2 }}-{{ index .Captures 3 | toLowerCase }}.rs"

# Base source template.
template:
  source: ./src/main.rs
  modifier: |
    // Created by {{ .Author }} at {{ .Time }}
    // {{ .Url }}
    // {{ .Title }}

    {{ .Code }}

# Optional code post-processing.
code:
  modifier: |
    #!/usr/bin/env rust-script

    //! ```cargo
