# Library injection.
lib:
  regex: "use\\s*(super::)?{{.Name}}(::|;)"
  include:
    cpio: "./src/cpio.rs"

# Compilation.
compiler:
  name: Rust
  source: main.rs
  compile: sh
  args:
    - -c
    - |
      while pgrep -x cargo >/dev/null; do
        sleep 0.05
      done
  run: rust-script main.rs

# Behaviour
create_file: true
run_on_save: true

